'use strict';

// MODULES //

var category10 = require( '@stdlib/plot/color-schemes/category10' );


// MAIN //

/**
* Returns defaults.
*
* @private
* @returns {Object} defaults
*
* @example
* var obj = defaults();
* // returns {...}
*/
function defaults() {
	return {
		// Line colors:
		'colors': category10(),

		// Line opacity:
		'lineOpacity': [ 1.0 ],

		// Line style(s):
		'lineStyle': [ '-' ],

		// Line width(s) (in pixels):
		'lineWidth': [ 2 ]
	};
}


// EXPORTS //

module.exports = defaults;
